import subprocess, re, os
def g(*a): return subprocess.run(['git','-C','/tmp/shurik-workspace-PJD9B3',*a],capture_output=True,text=True).stdout
# collect all friend-message commits
branches=['friend/rachel','friend/monica','friend/phoebe','friend/joey','friend/chandler','friend/ross']
commits={}
for b in branches:
    out=g('log','--format=%H','origin/'+b)
    for sha in out.split():
        body=g('show','-s','--format=%B',sha)
        if 'Friend-Message: 1' in body:
            commits[sha]=body
print('total friend-message commits:',len(commits))
# collect sources recorded in main
files=[f'S01/E0{i}.md' for i in (1,2,3)]
recorded={}
for f in files:
    txt=g('show','origin/main:'+f)
