dups={k:v for k,v in recorded.items() if len(v)>1}
print('duplicate-recorded SHAs:',dups)
missing=[s for s in commits if s not in recorded]
print('commits not yet in main transcript:',len(missing))
for s in missing: print('   ',s[:8],commits[s].splitlines()[0])
unknown=[s for s in recorded if s not in commits]
